$updated=[];
foreach($cats as $id=>$copy){
  $term=get_term($id,'category');
  if(!$term || is_wp_error($term)) continue;
  $r=wp_update_term($id,'category',['description'=>$copy['es']]);
  if(is_wp_error($r)) throw new Exception('Category update failed '.$id.': '.$r->get_error_message());
  update_term_meta($id,'_en_US_description',$copy['en']);
  update_term_meta($id,'_en_US_published','1');
  $updated[]=['id'=>$id,'slug'=>$term->slug,'es_words'=>str_word_count(wp_strip_all_tags($copy['es'])),'en_words'=>str_word_count(wp_strip_all_tags($copy['en']))];
}

$placeholder_id=13442;
if(get_post($placeholder_id)){
  update_post_meta($placeholder_id,'_wp_attachment_image_alt','');
  wp_update_post(['ID'=>$placeholder_id,'post_title'=>'El Mercado de Origen']);
}

echo "EMDO_CATEGORY_HUBS_BEGIN\n";
echo wp_json_encode(['categories'=>$updated,'placeholder'=>['id'=>$placeholder_id,'alt'=>(string)get_post_meta($placeholder_id,'_wp_attachment_image_alt',true),'title'=>(string)get_the_title($placeholder_id)]],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)."\n";
echo "EMDO_CATEGORY_HUBS_END\n";
